#include "common.h"
extern decltype(yuv2rgb_c_24_rgb) yuv2rgb_c_24_rgb_rvv;
namespace gather {
std::vector<std::string> entries(){return {"rgb"};}
Input generate(const std::string &entry,uint64_t seed){Input in;in.entry=entry;in.params={{"width",256},{"height",64}};RNG r(seed);r.fill(in.add<uint8_t>("Y","u8",256*64,"input"),256*64);r.fill(in.add<uint8_t>("U","u8",128*32,"gather,index"),128*32);r.fill(in.add<uint8_t>("V","u8",128*32,"gather,index"),128*32);in.add<uint8_t>("RGB","u8",256*64*3,"output",true);for(auto name:{"red","green","blue"})r.fill(in.add<uint8_t>(name,"u8",512,"gather"),512);auto gv=in.add<int32_t>("gV","i32",256,"gather,index");for(int i=0;i<256;++i){in.refs["rV"].push_back({"red",r.next()%100});in.refs["gU"].push_back({"green",60+r.next()%40});in.refs["bU"].push_back({"blue",r.next()%100});gv[i]=int(r.next()%81)-40;}return in;}
void validate(Input &in){auto w=in.p("width",0,16384),h=in.p("height",0,16384);require(w%4==0&&h%2==0,"width must be multiple of 4; height must be even");in.a<uint8_t>("Y","u8",w*h);in.a<uint8_t>("U","u8",w*h/4);in.a<uint8_t>("V","u8",w*h/4);in.a<uint8_t>("RGB","u8",w*h*3);auto gv=in.a<int32_t>("gV","i32",256);for(auto name:{"red","green","blue"}){auto it=in.arrays.find(name);require(it!=in.arrays.end(),"missing color table");in.a<uint8_t>(name,"u8",it->second.bytes.size());roles(in,name,"gather");}for(auto name:{"rV","gU","bU"}){auto &refs=in.r(name,256);for(auto &ref:refs){require(ref.target=="red"||ref.target=="green"||ref.target=="blue","color pointer must target a color table");size_t size=in.arrays.at(ref.target).bytes.size();require(ref.offset<=size&&size-ref.offset>=256,"color pointer out of range");if(std::string(name)=="gU")for(int j=0;j<256;++j){int64_t off=int64_t(ref.offset)+gv[j];require(off>=0&&uint64_t(off)<=size&&size-uint64_t(off)>=256,"green pointer plus gV out of range");}}}roles(in,"Y","input");roles(in,"U","gather,index");roles(in,"V","gather,index");roles(in,"RGB","output",true);roles(in,"gV","gather,index");}
std::unique_ptr<Case> make_case(const Input &in,Platform &p,bool use_rvv){auto c=std::make_unique<Case>(in,p);int w=in.params.at("width"),h=in.params.at("height");c->work.add("context",sizeof(SwsInternal),"state,gather,pointer");auto ctx=c->work.ptr<SwsInternal>("context");new(ctx) SwsInternal{};c->work.add("src",4*sizeof(uint8_t *),"pointer");c->work.add("dst",3*sizeof(uint8_t *),"pointer");c->work.add("strides",6*sizeof(int),"parameters");auto src=c->work.ptr<const uint8_t *>("src");auto dst=c->work.ptr<uint8_t *>("dst");auto strides=c->work.ptr<int>("strides");strides[0]=w;strides[1]=strides[2]=w/2;strides[3]=3*w;auto raw=c.get();c->rebind=[=,&in]{ctx->opts.dst_w=w;for(int i=0;i<256;++i){auto ref=in.refs.at("rV")[i];ctx->table_rV[i+YUVRGB_TABLE_HEADROOM]=raw->work.ptr<uint8_t>(ref.target)+ref.offset;ref=in.refs.at("gU")[i];ctx->table_gU[i+YUVRGB_TABLE_HEADROOM]=raw->work.ptr<uint8_t>(ref.target)+ref.offset;ref=in.refs.at("bU")[i];ctx->table_bU[i+YUVRGB_TABLE_HEADROOM]=raw->work.ptr<uint8_t>(ref.target)+ref.offset;ctx->table_gV[i+YUVRGB_TABLE_HEADROOM]=raw->work.ptr<int32_t>("gV")[i];}src[0]=raw->work.ptr<uint8_t>("Y");src[1]=raw->work.ptr<uint8_t>("U");src[2]=raw->work.ptr<uint8_t>("V");dst[0]=raw->work.ptr<uint8_t>("RGB");};auto fn=SELECT(yuv2rgb_c_24_rgb,yuv2rgb_c_24_rgb_rvv);c->call=[=]{raw->result=fn(ctx,src,strides,0,h,dst,strides+3);};return c;}
}
